/* The tile's own layout. Everything visual (surface, radius, hover) belongs to <Card>; this file
 * only places the two things Card cannot know about: a title and a menu trigger on one row, with
 * the trigger at the inline end.
 *
 * It was missing. The component shipped writing these three class names and no stylesheet ever
 * defined them, so the head stacked: the ⋮ trigger sat on its own line under the title, in every
 * app that adopted the tile. Caught the first time a screen outside the first app used it. */

.ws-tile-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: var(--space-2);
  min-inline-size: 0;
}

/* The title takes the room and wraps; the trigger keeps its size. */
.ws-tile-head .card-title {
  min-inline-size: 0;
}

.ws-tile-menu {
  flex: none;
  /* Pulls the quiet trigger back level with the title's cap height rather than its line box, so
   * the row reads as one line and not as an icon floating below the text. */
  margin-block-start: calc(var(--space-1) * -1);
}

import './LinkTile.css'
import type { ReactNode } from 'react'
import { IconButton } from '../IconButton'
import { Dropdown } from '../Dropdown'
import { Card, CardTitle } from '../Card'

/* Extracted from the Workshops and Transcripts list pages, which carried
 * byte-identical copies of this composition. Everything here is DS parts:
 * Card / CardTitle / IconButton / Dropdown. */

/** A clickable tile: navigates on click/Enter/Space, with an overflow (⋮) menu
 *  in its top-inline-end corner. The caller supplies the title, the menu items,
 *  the open handler and the body. 
 *
 * Copy: the title is the destination's own name, so a reader arriving there
 * recognises where they are.
 */
export function LinkTile({
  title,
  menuLabel,
  menu,
  onOpen,
  children,
}: {
  title: ReactNode
  /** Accessible name for the ⋮ trigger. */
  menuLabel: string
  /** Dropdown items (DropdownItem elements). */
  menu: ReactNode
  onOpen: () => void
  /** Tile body below the head — meta, snippet, badges. */
  children?: ReactNode
}) {
  return (
    <Card
      interactive
      role="link"
      tabIndex={0}
      className="ws-tile"
      onClick={onOpen}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onOpen()
        }
      }}
    >
      <div className="ws-tile-head">
        <CardTitle as="h2">{title}</CardTitle>
        {/* The menu lives inside a link-tile, so Enter on the ⋮ trigger would
            reach the tile's own key handler and navigate away instead of opening
            the menu. Clicks need no guard here: <Dropdown> already stops those
            on both the trigger and the menu, and LinkTile.test.tsx holds it to
            that from the outside, wherever the guard lives. */}
        <span className="ws-tile-menu" role="presentation" onKeyDown={(e) => e.stopPropagation()}>
          <Dropdown
            trigger={({ isOpen, ...triggerProps }) => (
              <IconButton
                {...triggerProps}
                data-open={isOpen || undefined}
                icon="more_vert"
                size="sm"
                variant="quiet"
                reveal
                aria-label={menuLabel}
              />
            )}
          >
            {menu}
          </Dropdown>
        </span>
      </div>
      {children}
    </Card>
  )
}
